// <ol class=\"nds-stepper\"> › <li class=\"nds-stepper-item\"> › <button class=\"nds-stepper-trigger\">
const stepper = createStepper({
  'aria-label': 'Progresso do cadastro',
  labels: { completed: 'Etapa concluída', current: 'Etapa atual' },
  onStepSelect: irPara,
});

const conta = createStepperItem({ step: 1 });
const gatilhoConta = createStepperTrigger();
gatilhoConta.append(
  createStepperIndicator(),
  createStepperTitle({ text: 'Conta' }),
  createStepperDescription({ text: 'Seus dados' }),
);
conta.append(gatilhoConta, createStepperSeparator());

stepper.append(conta);

// Resolve o estado de cada etapa a partir do valor atual do fluxo.
setStepperValue(stepper, 2);

extensibilityCode.react:
// Etapa fora de ordem marcada como concluída
<StepperItem step={4} completed>…</StepperItem>

// Etapa que ainda não pode ser aberta
<StepperItem step={3} disabled>…</StepperItem>

// Indicador com conteúdo próprio no lugar do número
<StepperIndicator><CreditCard aria-hidden="true" /></StepperIndicator>

extensibilityCode.vanilla:
// Etapa fora de ordem marcada como concluída
const extra = createStepperItem({ step: 4, completed: true });

// Etapa que ainda não pode ser aberta
const bloqueada = createStepperItem({ step: 3, disabled: true });

// Indicador com conteúdo próprio no lugar do número
// `content` marca o indicador como `data-custom`; sem isso
// `setStepperValue` reescreveria o icone no proximo avanco.
const indicator = createStepperIndicator({ content: iconeCartao() });

customizationCode.web:
/* O traço ocupa a largura que sobra: para uma linha contínua entre
   etapas, deixe o item crescer. */
.checkout-stepper .nds-stepper-item { flex: 1; }
.checkout-stepper .nds-stepper-item:last-child { flex: 0; }

/* Em telas estreitas, só a etapa atual mantém o rótulo visível. */
@media (max-width: 40rem) {
  .checkout-stepper .nds-stepper-item:not([data-state="active"]) .nds-stepper-title,
  .checkout-stepper .nds-stepper-description { display: none; }
}

